import{_ as t,o as s,c as o,a2 as r}from"./chunks/framework.Zh78JZbW.js";const a="/kodus-releases/screenshots/amis.png",v=JSON.parse('{"title":"Amis","description":"","frontmatter":{},"headers":[],"relativePath":"guide/amis.md","filePath":"guide/amis.md"}'),i={name:"guide/amis.md"};function n(u,e,l,d,m,g){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="amis" tabindex="-1">Amis <a class="header-anchor" href="#amis" aria-label="Permalink to &quot;Amis&quot;">​</a></h1><p>Ajoutez vos amis avec leur pseudo Kodus : vous voyez qui est en ligne et, s&#39;ils le souhaitent, à quoi ils jouent. Cliquez sur le bouton <strong>Amis</strong> en haut de l&#39;accueil (l&#39;icône à deux personnages).</p><p><img src="'+a+'" alt="Page Amis : liste d&#39;amis avec leur présence, ajout d&#39;un ami et demandes reçues"></p><h2 id="ajouter-un-ami" tabindex="-1">Ajouter un ami <a class="header-anchor" href="#ajouter-un-ami" aria-label="Permalink to &quot;Ajouter un ami&quot;">​</a></h2><ol><li>Saisissez le pseudo de votre ami dans <strong>Ajouter un ami</strong>, puis cliquez sur <strong>Envoyer</strong>.</li><li>Votre ami voit la demande dans <strong>Demandes reçues</strong> et choisit <strong>Accepter</strong> ou <strong>Refuser</strong>.</li></ol><p>Si votre ami vous avait déjà envoyé une demande, vous devenez amis tout de suite.</p><ul><li>Vous pouvez envoyer <strong>4 demandes par jour</strong>.</li><li>Votre ami doit utiliser Kodus 0.5 ou plus récent.</li><li>Un chiffre sur le bouton <strong>Amis</strong> de l&#39;accueil indique les demandes en attente ; un point vert signale qu&#39;un ami est en ligne.</li></ul><h2 id="ce-que-vos-amis-voient" tabindex="-1">Ce que vos amis voient <a class="header-anchor" href="#ce-que-vos-amis-voient" aria-label="Permalink to &quot;Ce que vos amis voient&quot;">​</a></h2><p>En haut à droite de la page, <strong>Ma présence</strong> règle ce que vos amis voient de vous :</p><table tabindex="0"><thead><tr><th>Réglage</th><th>Ce que vos amis voient</th></tr></thead><tbody><tr><td><strong>Tout montrer</strong></td><td>Si vous êtes en ligne, et l&#39;instance à laquelle vous jouez (« En jeu : Create (1.21.1 NeoForge) »)</td></tr><tr><td><strong>En ligne seulement</strong> (par défaut)</td><td>Seulement si vous êtes en ligne, pas à quoi vous jouez</td></tr><tr><td><strong>Invisible</strong></td><td>Vous apparaissez toujours hors ligne</td></tr></tbody></table><p>Seuls vos amis voient votre présence. Elle se met à jour environ toutes les minutes.</p><h2 id="retirer-ou-bloquer" tabindex="-1">Retirer ou bloquer <a class="header-anchor" href="#retirer-ou-bloquer" aria-label="Permalink to &quot;Retirer ou bloquer&quot;">​</a></h2><p>Passez la souris sur un ami pour afficher <strong>Retirer</strong> et <strong>Bloquer</strong>.</p><ul><li><strong>Retirer</strong> : vous n&#39;êtes plus amis. Il peut vous renvoyer une demande.</li><li><strong>Bloquer</strong> : vous n&#39;êtes plus amis et il ne peut plus vous envoyer de demande. Il n&#39;en est pas averti.</li></ul><p>Vous pouvez aussi bloquer un joueur depuis une demande reçue. La liste <strong>Joueurs bloqués</strong>, en bas à droite, permet de les débloquer.</p>',15)])])}const c=t(i,[["render",n]]);export{v as __pageData,c as default};
